option.value:
{
  "$schema": "https://unpkg.com/@camunda/zeebe-element-templates-json-schema/resources/schema.json",
  "name": "Database Polling Connector",
  "id": "io.camunda.connector.dbpoller.v1",
  "version": 1,
  "description": "Periodically polls a JDBC database and correlates each row as a BPMN message.",
  "documentationRef": "https://github.com/camunda-community-hub/connector-db-poller",
  "category": {
    "id": "connectors",
    "name": "Connectors"
  },
  "appliesTo": ["bpmn:StartEvent", "bpmn:IntermediateCatchEvent"],
  "elementType": {
    "value": "bpmn:StartEvent",
    "eventDefinition": "bpmn:MessageEventDefinition"
  },
  "groups": [
    { "id": "connection",  "label": "Connection"  },
    { "id": "polling",     "label": "Polling"     },
    { "id": "watermark",   "label": "Watermark"   },
    { "id": "correlation", "label": "Correlation" },
    { "id": "resilience",  "label": "Resilience"  }
  ],
  "properties": [
    {
      "type": "Hidden",
      "value": "io.camunda:connector-db-poller:1",
      "binding": { "type": "zeebe:property", "name": "inbound.type" }
    },
    {
      "label": "JDBC URL",
      "description": "e.g. jdbc:postgresql://host:5432/mydb",
      "group": "connection",
      "type": "String",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.jdbcUrl" },
      "constraints": { "notEmpty": true }
    },
    {
      "label": "Username",
      "group": "connection",
      "type": "String",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.username" },
      "constraints": { "notEmpty": true }
    },
    {
      "label": "Password",
      "group": "connection",
      "type": "String",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.password" },
      "constraints": { "notEmpty": true }
    },
    {
      "label": "Dialect (auto-detect if blank)",
      "group": "connection",
      "type": "Dropdown",
      "value": "",
      "choices": [
        { "name": "Auto-detect", "value": "" },
        { "name": "PostgreSQL",  "value": "POSTGRES" },
        { "name": "MySQL",       "value": "MYSQL" },
        { "name": "H2",          "value": "H2" }
      ],
      "binding": { "type": "zeebe:property", "name": "inbound.dialect" }
    },
    {
      "label": "Connection Timeout (ms)",
      "group": "connection",
      "type": "String",
      "value": "5000",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.connectionTimeoutMs" }
    },
    {
      "label": "Pool Max Size",
      "group": "connection",
      "type": "String",
      "value": "2",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.poolMaxSize" }
    },
    {
      "label": "Polling Query",
      "description": "SELECT query with :lastWatermark placeholder. Example: SELECT * FROM orders WHERE updated_at > :lastWatermark ORDER BY updated_at",
      "group": "polling",
      "type": "Text",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.pollingQuery" },
      "constraints": { "notEmpty": true }
    },
    {
      "label": "Polling Interval (seconds)",
      "group": "polling",
      "type": "String",
      "value": "30",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.pollingIntervalSeconds" }
    },
    {
      "label": "Batch Size",
      "group": "polling",
      "type": "String",
      "value": "100",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.batchSize" }
    },
    {
      "label": "Query Timeout (seconds)",
      "group": "polling",
      "type": "String",
      "value": "30",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.queryTimeoutSeconds" }
    },
    {
      "label": "Watermark Column",
      "description": "Column name used to track polling progress (e.g. updated_at)",
      "group": "watermark",
      "type": "String",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.watermarkColumn" },
      "constraints": { "notEmpty": true }
    },
    {
      "label": "Watermark Type",
      "group": "watermark",
      "type": "Dropdown",
      "value": "TIMESTAMP",
      "choices": [
        { "name": "Timestamp",   "value": "TIMESTAMP" },
        { "name": "Big Integer", "value": "BIGINT" },
        { "name": "UUID",        "value": "UUID" },
        { "name": "String",      "value": "STRING" }
      ],
      "binding": { "type": "zeebe:property", "name": "inbound.watermarkType" }
    },
    {
      "label": "Initial Watermark",
      "description": "Starting value for the watermark. Leave blank for type-appropriate default (EPOCH / 0 / nil UUID / empty string).",
      "group": "watermark",
      "type": "String",
      "feel": "optional",
      "optional": true,
      "binding": { "type": "zeebe:property", "name": "inbound.initialWatermark" }
    },
    {
      "label": "Instance ID",
      "description": "Logical identifier included in every RowPayload metadata block.",
      "group": "watermark",
      "type": "String",
      "feel": "optional",
      "optional": true,
      "binding": { "type": "zeebe:property", "name": "inbound.instanceId" }
    },
    {
      "label": "Correlation Key",
      "description": "FEEL expression to extract the correlation key from the row payload.",
      "group": "correlation",
      "type": "String",
      "feel": "required",
      "binding": { "type": "zeebe:property", "name": "correlationKey" },
      "constraints": { "notEmpty": true }
    },
    {
      "label": "Message ID",
      "description": "FEEL expression for deduplication message ID (optional).",
      "group": "correlation",
      "type": "String",
      "feel": "optional",
      "optional": true,
      "binding": { "type": "zeebe:property", "name": "messageId" }
    },
    {
      "label": "Activation Condition",
      "description": "FEEL expression evaluated on the row payload; message is only correlated when true.",
      "group": "correlation",
      "type": "String",
      "feel": "optional",
      "optional": true,
      "binding": { "type": "zeebe:property", "name": "activationCondition" }
    },
    {
      "label": "Result Variable",
      "description": "Process variable name to store the correlated row payload.",
      "group": "correlation",
      "type": "String",
      "feel": "optional",
      "optional": true,
      "binding": { "type": "zeebe:property", "name": "resultVariable" }
    },
    {
      "label": "Max Consecutive Failures",
      "group": "resilience",
      "type": "String",
      "value": "5",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.maxConsecutiveFailures" }
    },
    {
      "label": "Circuit Breaker Threshold",
      "description": "Consecutive failures before health is reported as DOWN.",
      "group": "resilience",
      "type": "String",
      "value": "10",
      "feel": "optional",
      "binding": { "type": "zeebe:property", "name": "inbound.circuitBreakerThreshold" }
    }
  ]
}

package io.camunda.connector.dbpoller;

import io.camunda.connector.api.annotation.InboundConnector;
import io.camunda.connector.api.inbound.Activity;
import io.camunda.connector.api.inbound.Health;
import io.camunda.connector.api.inbound.InboundConnectorContext;
import io.camunda.connector.api.inbound.InboundConnectorExecutable;
import io.camunda.connector.api.inbound.Severity;
import io.camunda.connector.dbpoller.exception.DbPollerException;
import io.camunda.connector.dbpoller.service.DataSourceFactory;
import io.camunda.connector.dbpoller.service.InMemoryWatermarkStore;
import io.camunda.connector.dbpoller.service.PollingService;
import io.camunda.connector.dbpoller.service.WatermarkStore;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.sql.DataSource;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/** Inbound connector that polls a JDBC database on a fixed-delay schedule. */
@InboundConnector(
        name = "Database Polling Connector",
        type = DbPollerConnectorExecutable.TYPE
)
public class DbPollerConnectorExecutable implements InboundConnectorExecutable<InboundConnectorContext> {

    private static final Logger LOG = LoggerFactory.getLogger(DbPollerConnectorExecutable.class);

    /** Connector type identifier used in BPMN element templates. */
    public static final String TYPE = "io.camunda:connector-db-poller:1";

    private InboundConnectorContext context;
    private DbPollerProperties properties;
    private DataSource dataSource;
    private WatermarkStore watermarkStore;
    private PollingService pollingService;
    private ScheduledExecutorService scheduler;
    private ScheduledFuture<?> pollHandle;

    /**
     * Activates the connector: binds and validates properties, initialises the
     * data source and watermark store, then starts the daemon polling thread.
     *
     * @param context the inbound connector context provided by the runtime
     * @throws DbPollerException if activation fails for any reason
     */
    @Override
    public void activate(InboundConnectorContext context) {
        this.context = context;
        this.properties = context.bindProperties(DbPollerProperties.class);
        this.properties.validate();

        LOG.info("Activating DB Poller: dialect={}, interval={}s, batchSize={}",
                properties.getDialect(),
                properties.getPollingIntervalSeconds(),
                properties.getBatchSize());

        try {
            dataSource = DataSourceFactory.build(properties);
            watermarkStore = new InMemoryWatermarkStore(properties.parsedInitialWatermark());
            pollingService = new PollingService(context, properties, dataSource, watermarkStore);

            scheduler = Executors.newSingleThreadScheduledExecutor(r -> {
                var t = new Thread(r, "db-poller-" + safeProcessId(context));
                t.setDaemon(true);
                return t;
            });

            pollHandle = scheduler.scheduleWithFixedDelay(
                    this::safePoll,
                    0,
                    properties.getPollingIntervalSeconds(),
                    TimeUnit.SECONDS
            );

            context.reportHealth(Health.up());
            context.log(Activity.level(Severity.INFO)
                    .tag("activation")
                    .message("DB Poller activated successfully"));

        } catch (Exception ex) {
            LOG.error("Failed to activate DB Poller connector", ex);
            context.reportHealth(Health.down(ex));
            shutdownQuietly();
            throw new DbPollerException("Activation failed", ex);
        }
    }

    /**
     * Deactivates the connector by cancelling the scheduler and releasing resources.
     */
    @Override
    public void deactivate() {
        LOG.info("Deactivating DB Poller connector");
        shutdownQuietly();
    }

    private void safePoll() {
        try {
            pollingService.pollOnce();
            context.reportHealth(Health.up());
        } catch (Exception ex) {
            LOG.error("Poll iteration failed", ex);
            context.log(Activity.level(Severity.ERROR)
                    .tag("poll-failure")
                    .message(ex.getMessage()));
            if (pollingService.consecutiveFailures() >= properties.getCircuitBreakerThreshold()) {
                context.reportHealth(Health.down(ex));
            }
        }
    }

    private static String safeProcessId(InboundConnectorContext ctx) {
        try {
            return ctx.getDefinition().elements().get(0).bpmnProcessId();
        } catch (Exception ex) {
            return "unknown-process";
        }
    }

    private void shutdownQuietly() {
        if (pollHandle != null) {
            pollHandle.cancel(false);
        }
        if (scheduler != null) {
            scheduler.shutdown();
            try {
                if (!scheduler.awaitTermination(10, TimeUnit.SECONDS)) {
                    scheduler.shutdownNow();
                }
            } catch (InterruptedException ex) {
                Thread.currentThread().interrupt();
                scheduler.shutdownNow();
            }
        }
        if (dataSource instanceof AutoCloseable ac) {
            try {
                ac.close();
            } catch (Exception ignored) {
                // intentionally swallowed during shutdown
            }
        }
    }
}

package io.camunda.connector.dbpoller.dialect;

import io.camunda.connector.dbpoller.exception.DbPollerException;

import java.util.Arrays;
import java.util.stream.Collectors;

public enum DatabaseDialect {

    POSTGRES(
            "jdbc:postgresql:",
            "org.postgresql.Driver",
            "SELECT 1",
            "\"",
            batchSize -> " LIMIT " + batchSize
    ),
    MYSQL(
            "jdbc:mysql:",
            "com.mysql.cj.jdbc.Driver",
            "SELECT 1",
            "`",
            batchSize -> " LIMIT " + batchSize
    ),
    H2(
            "jdbc:h2:",
            "org.h2.Driver",
            "SELECT 1",
            "\"",
            batchSize -> " LIMIT " + batchSize
    );

    @FunctionalInterface
    public interface PaginationBuilder {
        String build(int batchSize);
    }

    private final String urlPrefix;
    private final String driverClass;
    private final String validationQuery;
    private final String identifierQuote;
    private final PaginationBuilder paginationBuilder;

    DatabaseDialect(String urlPrefix, String driverClass, String validationQuery,
                    String identifierQuote, PaginationBuilder paginationBuilder) {
        this.urlPrefix = urlPrefix;
        this.driverClass = driverClass;
        this.validationQuery = validationQuery;
        this.identifierQuote = identifierQuote;
        this.paginationBuilder = paginationBuilder;
    }

    public static DatabaseDialect fromUrl(String jdbcUrl) {
        if (jdbcUrl == null) {
            throw new DbPollerException("jdbcUrl must not be null");
        }
        String lower = jdbcUrl.toLowerCase();
        for (DatabaseDialect dialect : values()) {
            if (lower.startsWith(dialect.urlPrefix)) {
                return dialect;
            }
        }
        String supported = Arrays.stream(values())
                .map(d -> d.urlPrefix)
                .collect(Collectors.joining(", "));
        throw new DbPollerException(
                "No dialect found for jdbcUrl '" + jdbcUrl + "'. Supported prefixes: " + supported);
    }

    public String driverClass() {
        return driverClass;
    }

    public String validationQuery() {
        return validationQuery;
    }

    public String quoteIdentifier(String identifier) {
        String stripped = identifier.replace(identifierQuote, "");
        return identifierQuote + stripped + identifierQuote;
    }

    public String paginationClause(int batchSize) {
        return paginationBuilder.build(batchSize);
    }
}

package io.camunda.connector.dbpoller.service;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import io.camunda.connector.dbpoller.DbPollerProperties;
import io.camunda.connector.dbpoller.dialect.DatabaseDialect;
import io.camunda.connector.dbpoller.exception.DbPollerException;

import javax.sql.DataSource;

/** Factory that builds a configured {@link HikariDataSource} from connector properties. */
public final class DataSourceFactory {

    private DataSourceFactory() {}

    /**
     * Builds a read-only {@link DataSource} pool from the supplied properties.
     *
     * @param props validated connector properties
     * @return a fully initialised {@link HikariDataSource}
     * @throws DbPollerException if the dialect cannot be resolved or the pool cannot start
     */
    public static DataSource build(DbPollerProperties props) {
        DatabaseDialect dialect = props.getDialect();
        if (dialect == null) {
            throw new DbPollerException(
                    "Dialect could not be resolved; set jdbcUrl or dialect explicitly");
        }

        try {
            var cfg = new HikariConfig();
            cfg.setJdbcUrl(props.getJdbcUrl());
            cfg.setUsername(props.getUsername());
            cfg.setPassword(props.getPassword());
            cfg.setDriverClassName(dialect.driverClass());
            cfg.setMaximumPoolSize(props.getPoolMaxSize());
            cfg.setMinimumIdle(0);
            cfg.setConnectionTimeout(props.getConnectionTimeoutMs());
            cfg.setConnectionTestQuery(dialect.validationQuery());
            cfg.setPoolName("db-poller-" + props.getPollingQueryHash());
            cfg.setReadOnly(true);
            cfg.setAutoCommit(true);

            long idleTimeout = Math.max(
                    30_000L,
                    (long) props.getPollingIntervalSeconds() * 1_000 + 10_000);
            cfg.setIdleTimeout(idleTimeout);

            return new HikariDataSource(cfg);
        } catch (RuntimeException ex) {
            throw new DbPollerException("Failed to initialize HikariCP pool", ex);
        }
    }
}

package io.camunda.connector.dbpoller.service;

import io.camunda.connector.api.inbound.Activity;
import io.camunda.connector.api.inbound.InboundConnectorContext;
import io.camunda.connector.api.inbound.Severity;
import io.camunda.connector.dbpoller.DbPollerProperties;
import io.camunda.connector.dbpoller.exception.DbPollerException;
import io.camunda.connector.dbpoller.model.RowPayload;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.sql.DataSource;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.sql.Types;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

/** Executes one polling iteration against the configured database. */
public class PollingService {

    private static final Logger LOG = LoggerFactory.getLogger(PollingService.class);
    private static final String WATERMARK_PLACEHOLDER = ":lastWatermark";

    private final InboundConnectorContext context;
    private final DbPollerProperties props;
    private final DataSource dataSource;
    private final WatermarkStore watermarkStore;
    private final AtomicInteger consecutiveFailures = new AtomicInteger(0);

    /**
     * Creates a new {@code PollingService}.
     *
     * @param context        the inbound connector context for correlation and logging
     * @param props          validated connector properties
     * @param dataSource     the pooled data source to query
     * @param watermarkStore the store tracking the current high-water mark
     */
    public PollingService(InboundConnectorContext context,
                          DbPollerProperties props,
                          DataSource dataSource,
                          WatermarkStore watermarkStore) {
        this.context = context;
        this.props = props;
        this.dataSource = dataSource;
        this.watermarkStore = watermarkStore;
    }

    /**
     * Executes one poll iteration: queries the database from the current watermark,
     * correlates each row as a BPMN message, and advances the watermark to the
     * highest value seen.
     *
     * @throws DbPollerException on SQL errors or correlation failures
     */
    public void pollOnce() {
        long startNanos = System.nanoTime();
        Object watermark = watermarkStore.read();
        String sql = buildSql();

        int rowsRead = 0;
        Object highestWatermarkSeen = null;

        try (var conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setQueryTimeout(props.getQueryTimeoutSeconds());
            bindWatermark(ps, 1, watermark);

            try (ResultSet rs = ps.executeQuery()) {
                ResultSetMetaData md = rs.getMetaData();
                while (rs.next()) {
                    var row = mapRow(rs, md);
                    Object rowWatermark = row.get(props.getWatermarkColumn());
                    var metadata = new RowPayload.Metadata(
                            props.getDialect().name(),
                            rowWatermark,
                            Instant.now(),
                            props.getInstanceId()
                    );
                    var payload = new RowPayload(row, metadata);
                    correlate(payload, rowWatermark);
                    highestWatermarkSeen = rowWatermark;
                    rowsRead++;
                }
            }

        } catch (SQLException ex) {
            consecutiveFailures.incrementAndGet();
            throw new DbPollerException("SQL error during poll: " + ex.getMessage(), ex);
        } catch (RuntimeException ex) {
            consecutiveFailures.incrementAndGet();
            throw ex;
        }

        if (rowsRead > 0 && highestWatermarkSeen != null) {
            watermarkStore.write(highestWatermarkSeen);
        }

        consecutiveFailures.set(0);

        long elapsedMs = (System.nanoTime() - startNanos) / 1_000_000;
        LOG.info("Polled {} row(s) in {} ms; watermark={}", rowsRead, elapsedMs, watermark);
        context.log(Activity.level(Severity.INFO)
                .tag("poll")
                .message(String.format("Polled %d row(s) in %d ms", rowsRead, elapsedMs)));
    }

    /** Returns the number of consecutive polling failures since the last success. */
    public int consecutiveFailures() {
        return consecutiveFailures.get();
    }

    /**
     * Builds the SQL to execute: replaces the watermark placeholder with {@code ?}
     * and appends a pagination clause if the query does not already contain one.
     */
    String buildSql() {
        String sql = props.getPollingQuery().replace(WATERMARK_PLACEHOLDER, "?");
        String upper = sql.toUpperCase();
        if (!upper.contains(" LIMIT ") && !upper.contains(" FETCH ") && !upper.contains(" TOP ")) {
            sql = sql + props.getDialect().paginationClause(props.getBatchSize());
        }
        return sql;
    }

    private void correlate(RowPayload payload, Object rowWatermark) {
        try {
            context.correlateWithResult(payload);
        } catch (Exception ex) {
            throw new DbPollerException(
                    "Correlation failed for row with watermark=" + rowWatermark + ": " + ex.getMessage(),
                    ex);
        }
    }

    void bindWatermark(PreparedStatement ps, int idx, Object value) throws SQLException {
        if (value == null) {
            ps.setNull(idx, Types.VARCHAR);
            return;
        }
        switch (props.getWatermarkType()) {
            case TIMESTAMP -> {
                Instant instant = (value instanceof Instant i)
                        ? i
                        : Instant.parse(value.toString());
                ps.setTimestamp(idx, Timestamp.from(instant));
            }
            case BIGINT -> ps.setLong(idx, ((Number) value).longValue());
            case UUID -> {
                UUID uuid = (value instanceof UUID u)
                        ? u
                        : UUID.fromString(value.toString());
                ps.setObject(idx, uuid);
            }
            case STRING -> ps.setString(idx, value.toString());
        }
    }

    static Map<String, Object> mapRow(ResultSet rs, ResultSetMetaData md) throws SQLException {
        int count = md.getColumnCount();
        var map = new LinkedHashMap<String, Object>(count * 2);
        for (int i = 1; i <= count; i++) {
            map.put(md.getColumnLabel(i), normalize(rs.getObject(i)));
        }
        return map;
    }

    private static Object normalize(Object value) {
        if (value == null) return null;
        if (value instanceof java.sql.Timestamp ts) return ts.toInstant();
        if (value instanceof java.sql.Date d) return d.toLocalDate();
        if (value instanceof java.sql.Time t) return t.toLocalTime();
        return value;
    }
}

package io.camunda.connector.dbpoller.service;

/**
 * Thread-safe store for the polling watermark value.
 *
 * <p>Implementations MUST be thread-safe. All reads and writes may occur
 * concurrently from the polling thread and any management thread.
 */
public interface WatermarkStore {

    /** Returns the current watermark value, or the initial value if never written. */
    Object read();

    /** Persists the given watermark value so subsequent reads reflect it. */
    void write(Object watermark);

    /** Releases any resources held by this store. Default implementation is a no-op. */
    default void close() {
        // no-op
    }
}

package io.camunda.connector.dbpoller;

import io.camunda.connector.dbpoller.dialect.DatabaseDialect;
import io.camunda.connector.dbpoller.exception.DbPollerException;
import org.junit.jupiter.api.Test;

import java.time.Instant;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class DbPollerPropertiesTest {

    private static DbPollerProperties baseProps() {
        var props = new DbPollerProperties();
        props.setJdbcUrl("jdbc:postgresql://localhost:5432/test");
        props.setUsername("u");
        props.setPassword("p");
        props.setWatermarkColumn("updated_at");
        props.setPollingQuery("SELECT * FROM t WHERE updated_at > :lastWatermark ORDER BY updated_at");
        return props;
    }

    @Test
    void validate_rejectsMissingJdbcUrl() {
        var props = baseProps();
        props.setJdbcUrl(null);

        assertThatThrownBy(props::validate)
                .isInstanceOf(DbPollerException.class)
                .hasMessageContaining("jdbcUrl is required");
    }

    @Test
    void validate_rejectsMissingUsername() {
        var props = baseProps();
        props.setUsername("");

        assertThatThrownBy(props::validate)
                .isInstanceOf(DbPollerException.class)
                .hasMessageContaining("username is required");
    }

    @Test
    void validate_rejectsPollingQueryWithoutWatermarkPlaceholder() {
        var props = baseProps();
        props.setPollingQuery("SELECT * FROM t ORDER BY id");

        assertThatThrownBy(props::validate)
                .isInstanceOf(DbPollerException.class)
                .hasMessageContaining(":lastWatermark");
    }

    @Test
    void parsedInitialWatermark_parsesTimestamp() {
        var props = baseProps();
        props.setWatermarkType(DbPollerProperties.WatermarkType.TIMESTAMP);
        props.setInitialWatermark("2024-01-15T10:30:00Z");

        assertThat(props.parsedInitialWatermark())
                .isEqualTo(Instant.parse("2024-01-15T10:30:00Z"));
    }

    @Test
    void parsedInitialWatermark_parsesBigint() {
        var props = baseProps();
        props.setWatermarkType(DbPollerProperties.WatermarkType.BIGINT);
        props.setInitialWatermark("12345");

        assertThat(props.parsedInitialWatermark()).isEqualTo(12345L);
    }

    @Test
    void parsedInitialWatermark_passesStringThrough() {
        var props = baseProps();
        props.setWatermarkType(DbPollerProperties.WatermarkType.STRING);
        props.setInitialWatermark("hello");

        assertThat(props.parsedInitialWatermark()).isEqualTo("hello");
    }

    @Test
    void parsedInitialWatermark_throwsOnBadBigint() {
        var props = baseProps();
        props.setWatermarkType(DbPollerProperties.WatermarkType.BIGINT);
        props.setInitialWatermark("abc");

        assertThatThrownBy(props::parsedInitialWatermark)
                .isInstanceOf(DbPollerException.class)
                .hasMessageContaining("BIGINT");
    }

    @Test
    void databaseDialect_fromUrl_detectsPostgres() {
        assertThat(DatabaseDialect.fromUrl("jdbc:postgresql://localhost/db"))
                .isEqualTo(DatabaseDialect.POSTGRES);
    }

    @Test
    void databaseDialect_fromUrl_detectsMysql() {
        assertThat(DatabaseDialect.fromUrl("jdbc:mysql://localhost/db"))
                .isEqualTo(DatabaseDialect.MYSQL);
    }

    @Test
    void databaseDialect_fromUrl_detectsH2() {
        assertThat(DatabaseDialect.fromUrl("jdbc:h2:mem:testdb"))
                .isEqualTo(DatabaseDialect.H2);
    }

    @Test
    void databaseDialect_fromUrl_throwsOnUnknown() {
        assertThatThrownBy(() -> DatabaseDialect.fromUrl("jdbc:oracle:thin:@localhost:1521:xe"))
                .isInstanceOf(DbPollerException.class)
                .hasMessageContaining("No dialect found");
    }

    @Test
    void getPollingQueryHash_isStableAndTwelveChars() {
        var props = baseProps();
        String hash1 = props.getPollingQueryHash();
        String hash2 = props.getPollingQueryHash();

        assertThat(hash1).hasSize(12);
        assertThat(hash1).isEqualTo(hash2);
    }
}
